#rf-root,.hf-root{--x3:#ddcfcd;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;}.cam{position:absolute;inset:0;animation:st-cam 4s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}.tx-out{transform:translateY(101%);animation:tx-out 0.5s cubic-bezier(.76,0,.24,1) 3.5s both}@keyframes tx-out{to{transform:translateY(0)}}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
