.n130{counter-reset:n130 var(--n130);animation:n130-c 1.8s cubic-bezier(.16,1,.3,1) 0.3s both}
.n130::after{content:counter(n130,decimal)}
@keyframes n130-c{from{--n130:0}to{--n130:3200}}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
